using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.AccessControl;
using System.Security.Principal;
using System.ServiceProcess;
using System.Threading;
using System.Web.Script.Serialization;
using ThinkPadModesV3;
internal static class CoolingSetup {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static void Protect(string directory,string sid){var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.SetOwner(new SecurityIdentifier("S-1-5-32-544"));foreach(string id in new[]{"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(id),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(directory,acl);}
 static void Write(string path,object data){Atomic.Write(path,Json.Serialize(data));}
 public static int Run(string report){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;if(File.Exists(report))return 75;
  string directory=Path.GetDirectoryName(typeof(CoolingSetup).Assembly.Location),target=null;bool created=false;byte[] infoBefore=null,desktopBefore=null,startupBefore=null;InstallationInfo prior=null;CoolingInstallation oldInstallation=null;
  try{
   prior=Paths.Info();if(prior.OwnerSid!=WindowsIdentity.GetCurrent().User.Value)throw new UnauthorizedAccessException("Le propriétaire de l'installation ne correspond pas");
   var manifest=Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(directory,"native-package.json")));string[] allowed={"ThinkPadModesCooling.exe","ThinkPadModesNativeUI.exe","qualification.json"};if(manifest.Count!=allowed.Length||manifest.Keys.Any(k=>!allowed.Contains(k)))throw new IOException("Paquet natif hors périmètre");foreach(string f in allowed)if(Digest.Of(Path.Combine(directory,f))!=manifest[f])throw new IOException("Empreinte différente : "+f);
   var q=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(directory,"qualification.json")));if(Convert.ToString(q["EvidenceSHA256"])!=CoolingPaths.Evidence||!(bool)q["ManualValidated"]||(bool)q["ZeroValidated"])throw new IOException("Qualification matérielle absente");
   LenovoOemTransport.Verify();Guid beforeAc=WindowsPower.Read(true),beforeDc=WindowsPower.Read(false);Reply baseline=PipeClient.Send("status");if(!baseline.Ok)throw new IOException(baseline.Error);bool startup=baseline.Snapshot.Startup=="ON";
   string desktop=Path.Combine(prior.Desktop,StartupIntegration.Shortcut),autolink=Path.Combine(prior.Startup,StartupIntegration.Shortcut);if(File.Exists(desktop))desktopBefore=File.ReadAllBytes(desktop);if(File.Exists(autolink))startupBefore=File.ReadAllBytes(autolink);
   if(File.Exists(CoolingPaths.InfoFile)){infoBefore=File.ReadAllBytes(CoolingPaths.InfoFile);oldInstallation=CoolingPaths.Info();if(oldInstallation.OwnerSid!=prior.OwnerSid||!oldInstallation.Directory.StartsWith(Path.Combine(Paths.Root,"versions")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||Digest.Of(Path.Combine(oldInstallation.Directory,"ThinkPadModesCooling.exe"))!=oldInstallation.ExecutableSHA256)throw new IOException("Installation native précédente non reconnue");using(var svc=new ServiceController(CoolingPaths.Service)){if(svc.Status!=ServiceControllerStatus.Stopped){CoolingReply auto=CoolingClient.Send("set","Auto");if(!auto.Ok)throw new IOException(auto.Error);svc.Stop();svc.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(20));}}}
   else if(ServiceController.GetServices().Any(s=>s.ServiceName==CoolingPaths.Service))throw new IOException("Service existant sans identité d'installation");
   using(var ec=new LenovoOemTransport(true))ec.SetBothOem(0x80);
   string priorFault=Path.Combine(CoolingPaths.Data,"fault.json");if(oldInstallation!=null&&oldInstallation.Version=="native-20261115-94129ddbf4e1"&&File.Exists(priorFault)){var reviewed=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(priorFault));string reason=Convert.ToString(reviewed["Error"]);if((bool)reviewed["AutomaticRestored"]&&(reason.StartsWith("Mode readback differs:")||reason.StartsWith("Le worker Lenovo s"))){string history=Path.Combine(CoolingPaths.Data,"fault-history");Directory.CreateDirectory(history);File.Move(priorFault,Path.Combine(history,Guid.NewGuid().ToString("N")+"-reviewed-upgrade.json"));}}
   string version="native-20261115-"+manifest["ThinkPadModesCooling.exe"].Substring(0,12).ToLowerInvariant();target=Path.Combine(Paths.Root,"versions",version);if(Directory.Exists(target))throw new IOException("Version déjà présente : inspecter le reçu avant une reprise");Directory.CreateDirectory(target);Protect(target,prior.OwnerSid);foreach(string file in allowed){File.Copy(Path.Combine(directory,file),Path.Combine(target,file),false);if(Digest.Of(Path.Combine(target,file))!=manifest[file])throw new IOException("Copie non vérifiée : "+file);}
   Directory.CreateDirectory(CoolingPaths.Data);Protect(CoolingPaths.Data,prior.OwnerSid);File.Copy(Path.Combine(directory,"qualification.json"),Path.Combine(CoolingPaths.Data,"qualification.json"),true);
   var info=new CoolingInstallation{OwnerSid=prior.OwnerSid,Directory=target,Version=version,ExecutableSHA256=manifest["ThinkPadModesCooling.exe"],UiSHA256=manifest["ThinkPadModesNativeUI.exe"]};Write(CoolingPaths.InfoFile,info);Write(Path.Combine(target,"native-package.json"),manifest);
   string exe=Path.Combine(target,"ThinkPadModesCooling.exe");if(oldInstallation==null){CoolingNative.Install(exe,prior.OwnerSid,startup);created=true;}else CoolingNative.ChangeBinary(exe);
   CoolingNative.Start();CoolingReply live=null;string last=null;long until=CoolingPaths.Tick+45000;while(CoolingPaths.Tick<until){try{live=CoolingClient.Send("status");if(live.Ok&&live.Snapshot.CanControl&&live.Snapshot.Fan1.HasValue&&live.Snapshot.Fan2.HasValue)break;last=live.Error??live.Snapshot.Detail;}catch(Exception e){last=e.Message;}Thread.Sleep(300);}if(live==null||!live.Ok||!live.Snapshot.CanControl)throw new IOException("Service natif non validé : "+last);
   StartupIntegration.CreateShortcut(Path.Combine(target,"ThinkPadModesNativeUI.exe"),desktop,"");if(startup)StartupIntegration.CreateShortcut(Path.Combine(target,"ThinkPadModesNativeUI.exe"),autolink,"--tray");
   if(WindowsPower.Read(true)!=beforeAc||WindowsPower.Read(false)!=beforeDc)throw new IOException("Profils Windows modifiés pendant l'installation");
   Write(report,new{UTC=DateTime.UtcNow.ToString("o"),Success=true,Version=version,Directory=target,FilesVerified=allowed.Length,Service=CoolingPaths.Service,LiveRpm=live.Snapshot,PowerProfilesPreserved=true,DesktopShortcut=desktop,StartupPreserved=startup,ZeroRequestEnabled=true,ForcedFanStopEnabled=false});return 0;
  }catch(Exception e){string rollback=null;try{if(created||oldInstallation!=null){using(var svc=new ServiceController(CoolingPaths.Service)){if(svc.Status!=ServiceControllerStatus.Stopped){svc.Stop();svc.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(20));}}}using(var ec=new LenovoOemTransport(true))ec.SetBothOem(0x80);if(created)CoolingNative.Remove();if(infoBefore==null&&target!=null&&File.Exists(CoolingPaths.InfoFile)&&CoolingPaths.Info().Directory==target)File.Delete(CoolingPaths.InfoFile);if(infoBefore!=null){File.WriteAllBytes(CoolingPaths.InfoFile,infoBefore);CoolingNative.ChangeBinary(Path.Combine(oldInstallation.Directory,"ThinkPadModesCooling.exe"));CoolingNative.Start();}if(prior!=null){string link=Path.Combine(prior.Desktop,StartupIntegration.Shortcut);if(desktopBefore!=null)File.WriteAllBytes(link,desktopBefore);string start=Path.Combine(prior.Startup,StartupIntegration.Shortcut);if(startupBefore!=null)File.WriteAllBytes(start,startupBefore);}}catch(Exception r){rollback=r.Message;}Write(report,new{UTC=DateTime.UtcNow.ToString("o"),Success=false,Error=e.Message,RollbackError=rollback,FilesPreserved=target});return 1;}
 }
}
